// Zip — draw one continuous line that visits every cell, starting at 1 and
// stepping through the numbered checkpoints in order. Walls block movement.
//
// A puzzle is generated by walking a random Hamiltonian path over the grid,
// walling off every adjacency the path does not use, then removing walls one at
// a time for as long as the solution stays unique.

import { Rng } from '../rng.js';
import { h, haptic } from '../ui.js';

const DIFFICULTIES = {
  easy: { label: 'Easy', width: 5, height: 5, checkpoints: 5, keepWalls: 0.56 },
  medium: { label: 'Medium', width: 6, height: 6, checkpoints: 6, keepWalls: 0.5 },
  hard: { label: 'Hard', width: 7, height: 7, checkpoints: 7, keepWalls: 0.46 },
};

const neighbourCache = new Map();

export function neighbours(width, height) {
  const key = `${width}x${height}`;
  const cached = neighbourCache.get(key);
  if (cached) return cached;
  const table = [];
  for (let r = 0; r < height; r++) {
    for (let c = 0; c < width; c++) {
      const list = [];
      if (r > 0) list.push((r - 1) * width + c);
      if (r < height - 1) list.push((r + 1) * width + c);
      if (c > 0) list.push(r * width + c - 1);
      if (c < width - 1) list.push(r * width + c + 1);
      table.push(list);
    }
  }
  neighbourCache.set(key, table);
  return table;
}

function edgeKey(a, b) {
  return a < b ? a * 1000 + b : b * 1000 + a;
}

/** Random Hamiltonian path over a width x height grid, or null if the search stalls. */
function randomPath(width, height, rng) {
  const size = width * height;
  const table = neighbours(width, height);
  const visited = new Uint8Array(size);
  const path = new Int32Array(size);
  let steps = 0;

  function onwardDegree(cell) {
    let count = 0;
    const list = table[cell];
    for (let i = 0; i < list.length; i++) if (!visited[list[i]]) count++;
    return count;
  }

  function walk(cell, depth) {
    visited[cell] = 1;
    path[depth] = cell;
    if (depth === size - 1) return true;
    if (++steps > 250000) return false;

    const options = [];
    for (const next of table[cell]) {
      if (!visited[next]) options.push(next);
    }
    // Always try the most constrained neighbour first — it keeps the search
    // near the "no dead ends" corridor instead of wandering into a corner.
    const ranked = options.map((next) => ({ next, degree: onwardDegree(next), tie: rng.next() }));
    ranked.sort((a, b) => a.degree - b.degree || a.tie - b.tie);

    for (const { next } of ranked) {
      if (walk(next, depth + 1)) return true;
    }
    visited[cell] = 0;
    return false;
  }

  for (let attempt = 0; attempt < 8; attempt++) {
    visited.fill(0);
    steps = 0;
    if (walk(rng.int(size), 0)) return Array.from(path);
  }
  return null;
}

/**
 * Checkpoints in the order they must be visited. Zip labels are step numbers
 * (1, 8, 15 …), so "in order" means the smallest unused label, not label + 1.
 */
function checkpointOrder(numbers) {
  const list = [];
  for (let cell = 0; cell < numbers.length; cell++) {
    if (numbers[cell]) list.push({ cell, label: numbers[cell] });
  }
  list.sort((a, b) => a.label - b.label);
  return list;
}

/**
 * Count solutions, stopping at `limit`. `budget` caps the search so a hard
 * uniqueness check cannot hang a phone; an aborted search reports `aborted`.
 */
export function countSolutions(puzzle, { limit = 2, budget = 200000 } = {}) {
  const { width, height, numbers, walls } = puzzle;
  const size = width * height;
  const table = neighbours(width, height);
  const wallSet = new Set(walls.map(([a, b]) => edgeKey(a, b)));
  const checkpoints = checkpointOrder(numbers);
  const checkpointIndex = new Map(checkpoints.map((entry, index) => [entry.cell, index]));
  const start = checkpoints[0]?.cell ?? -1;
  const visited = new Uint8Array(size);
  const found = [];
  let count = 0;
  let nodes = 0;
  let aborted = false;

  const trail = new Int32Array(size);

  function walk(cell, depth, nextCheckpoint) {
    trail[depth] = cell;
    if (depth === size - 1) {
      count++;
      if (found.length < limit) found.push(Array.from(trail));
      return;
    }
    if (++nodes > budget) {
      aborted = true;
      return;
    }
    for (const next of table[cell]) {
      if (visited[next]) continue;
      if (wallSet.has(edgeKey(cell, next))) continue;
      const order = checkpointIndex.get(next);
      if (order !== undefined && order !== nextCheckpoint) continue;
      visited[next] = 1;
      walk(next, depth + 1, order === undefined ? nextCheckpoint : nextCheckpoint + 1);
      visited[next] = 0;
      if (count >= limit || aborted) return;
    }
  }

  if (start >= 0) {
    visited[start] = 1;
    walk(start, 0, 1);
  }
  return { count, aborted, solutions: found };
}

export function solve(puzzle) {
  const result = countSolutions(puzzle, { limit: 1, budget: 2000000 });
  return result.solutions[0] ?? null;
}

export function generateZip(seed, difficulty = 'medium') {
  const config = DIFFICULTIES[difficulty] ?? DIFFICULTIES.medium;
  const { width, height } = config;
  const size = width * height;

  for (let attempt = 0; attempt < 24; attempt++) {
    const rng = new Rng(`${seed}|zip|${difficulty}|${attempt}`);
    const path = randomPath(width, height, rng);
    if (!path) continue;

    const order = new Int32Array(size);
    path.forEach((cell, index) => {
      order[cell] = index;
    });

    // Checkpoints: always 1 at the start and N at the end, plus a few on the way.
    const candidates = [];
    for (let i = 1; i < size - 1; i++) candidates.push(i);
    rng.shuffle(candidates);
    const inner = candidates.slice(0, Math.max(1, config.checkpoints - 2));
    inner.sort((a, b) => a - b);
    const checkpointIndexes = [0, ...inner, size - 1];

    const numbers = new Array(size).fill(0);
    for (const index of checkpointIndexes) numbers[path[index]] = index + 1;

    // Every adjacency the path does not use becomes a wall. That state is
    // unique by construction, so walls can only ever be removed.
    const wallCandidates = [];
    for (let a = 0; a < size; a++) {
      for (const b of neighbours(width, height)[a]) {
        if (a >= b) continue;
        const gap = Math.abs(order[a] - order[b]);
        if (gap !== 1) wallCandidates.push([a, b]);
      }
    }

    const kept = new Set(wallCandidates.map(([a, b]) => edgeKey(a, b)));
    let walls = wallCandidates.slice();
    let wallCount = walls.length;
    const target = Math.round(wallCandidates.length * config.keepWalls);

    for (const [a, b] of rng.shuffle(wallCandidates.slice())) {
      if (wallCount <= target) break;
      const key = edgeKey(a, b);
      kept.delete(key);
      const trial = walls.filter(([x, y]) => kept.has(edgeKey(x, y)));
      const check = countSolutions({ width, height, numbers, walls: trial }, { limit: 2, budget: 80000 });
      if (check.count === 1 && !check.aborted) {
        walls = trial;
        wallCount--;
      } else {
        kept.add(key);
      }
    }

    const puzzle = { width, height, numbers, walls, solution: path };
    const verify = countSolutions(puzzle, { limit: 2, budget: 400000 });
    if (verify.count === 1 && !verify.aborted) return puzzle;
  }

  throw new Error('zip: could not generate a unique puzzle');
}

function wallSegments(puzzle) {
  const { width, height, walls } = puzzle;
  return walls.map(([a, b]) => {
    const row = Math.floor(a / width);
    const col = a % width;
    // Horizontal neighbours share a vertical border, and vice versa.
    const horizontal = b === a + 1;
    if (horizontal) {
      const x = (col + 1) * 100;
      return { x1: x, y1: row * 100 + 11, x2: x, y2: row * 100 + 89 };
    }
    const y = (row + 1) * 100;
    return { x1: col * 100 + 11, y1: y, x2: col * 100 + 89, y2: y };
  });
}

const SVG_NS = 'http://www.w3.org/2000/svg';

function svgEl(name, attrs) {
  const node = document.createElementNS(SVG_NS, name);
  for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, value);
  return node;
}

export function createZip(host, { puzzle, saved, onChange, onSolve }) {
  const { width, height, numbers } = puzzle;
  const size = width * height;
  const table = neighbours(width, height);
  const wallSet = new Set(puzzle.walls.map(([a, b]) => edgeKey(a, b)));
  const checkpoints = checkpointOrder(numbers);
  const checkpointCells = new Set(checkpoints.map((entry) => entry.cell));

  let path = [];
  let solved = false;
  let dragPointer = null;
  let hints = 0;
  let message = '';

  const board = h('div', {
    class: 'zip-board',
    style: { '--cols': width, '--rows': height },
  });

  const grid = h('div', { class: 'zip-grid' });
  const cellNodes = [];
  for (let i = 0; i < size; i++) {
    const cell = h(
      'div',
      { class: 'zip-cell', dataset: { i: String(i) } },
      numbers[i] ? h('span', { class: 'zip-num', text: String(numbers[i]) }) : null,
    );
    if (numbers[i]) cell.classList.add('has-number');
    cellNodes.push(cell);
    grid.append(cell);
  }

  const svg = svgEl('svg', {
    class: 'zip-svg',
    viewBox: `0 0 ${width * 100} ${height * 100}`,
    preserveAspectRatio: 'none',
  });

  const gridPath = [];
  for (let c = 1; c < width; c++) gridPath.push(`M${c * 100} 0V${height * 100}`);
  for (let r = 1; r < height; r++) gridPath.push(`M0 ${r * 100}H${width * 100}`);
  svg.append(svgEl('path', { class: 'zip-gridlines', d: gridPath.join(' ') }));

  const line = svgEl('polyline', { class: 'zip-line', points: '' });
  svg.append(line);

  const wallGroup = svgEl('g', { class: 'zip-walls' });
  for (const segment of wallSegments(puzzle)) {
    wallGroup.append(
      svgEl('line', {
        x1: segment.x1,
        y1: segment.y1,
        x2: segment.x2,
        y2: segment.y2,
      }),
    );
  }
  svg.append(wallGroup);

  const startDot = svgEl('circle', { class: 'zip-start', r: 9, cx: 0, cy: 0, opacity: 0 });
  svg.append(startDot);

  board.append(grid, svg);

  const hint = h('p', { class: 'stage-hint' });
  const controls = h(
    'div',
    { class: 'stage-controls' },
    h(
      'button',
      {
        class: 'btn ghost',
        type: 'button',
        onclick: () => {
          if (solved) return;
          path = path.slice(0, -1);
          message = '';
          haptic();
          refresh();
        },
      },
      'Undo',
    ),
    h(
      'button',
      {
        class: 'btn ghost',
        type: 'button',
        onclick: () => {
          if (solved) return;
          path = [];
          message = '';
          haptic();
          refresh();
        },
      },
      'Clear',
    ),
    h('button', { class: 'btn ghost', type: 'button', onclick: () => giveHint() }, 'Hint'),
  );

  host.append(board, hint, controls);

  function centre(index) {
    const row = Math.floor(index / width);
    const col = index % width;
    return { x: col * 100 + 50, y: row * 100 + 50 };
  }

  function expectedLabel() {
    let seen = 0;
    for (const cell of path) if (checkpointCells.has(cell)) seen++;
    return checkpointCells.size > seen ? checkpoints[seen].label : Infinity;
  }

  function isAdjacent(a, b) {
    return table[a].includes(b);
  }

  function canAppend(index) {
    if (path.length === 0) return numbers[index] === 1;
    if (path.includes(index)) return false;
    const head = path[path.length - 1];
    if (!isAdjacent(head, index)) return false;
    if (wallSet.has(edgeKey(head, index))) return false;
    const label = numbers[index];
    if (label !== 0 && label !== expectedLabel()) return false;
    return true;
  }

  function refresh() {
    const covered = new Set(path);
    for (let i = 0; i < size; i++) {
      cellNodes[i].classList.toggle('on', covered.has(i));
      cellNodes[i].classList.toggle('head', path.length > 0 && path[path.length - 1] === i);
      const num = cellNodes[i].firstElementChild;
      if (num) num.classList.toggle('reached', covered.has(i));
    }

    if (path.length > 1) {
      line.setAttribute('points', path.map((cell) => {
        const { x, y } = centre(cell);
        return `${x},${y}`;
      }).join(' '));
    } else {
      line.setAttribute('points', '');
    }

    if (path.length > 0) {
      const { x, y } = centre(path[0]);
      startDot.setAttribute('cx', x);
      startDot.setAttribute('cy', y);
      startDot.setAttribute('opacity', '1');
    } else {
      startDot.setAttribute('opacity', '0');
    }

    hint.textContent = solved
      ? 'Solved'
      : message || `${path.length} of ${size} cells`;

    onChange();

    if (!solved && path.length === size) {
      solved = true;
      board.classList.add('solved');
      haptic([12, 40, 12]);
      onSolve();
    }
  }

  const HINT_STEPS = 3;

  function giveHint() {
    if (solved) return;
    hints++;
    const { solution } = puzzle;
    let correct = 0;
    while (correct < path.length && path[correct] === solution[correct]) correct++;

    if (correct < path.length) {
      path = solution.slice(0, Math.max(1, correct));
      message = 'Your line went off track here. Keep going from the end.';
      haptic([10, 30, 10]);
    } else {
      path = solution.slice(0, Math.min(size, correct + HINT_STEPS));
      message = 'Hint: the line continues like this.';
      haptic();
    }
    refresh();
  }

  function cellAt(clientX, clientY) {
    const node = document.elementFromPoint(clientX, clientY);
    const cell = node?.closest?.('.zip-cell');
    if (!cell) return -1;
    return Number(cell.dataset.i);
  }

  function apply(index) {
    if (index < 0 || solved) return false;
    message = '';
    if (path.includes(index)) {
      const at = path.indexOf(index);
      if (at === path.length - 1) return false;
      path = path.slice(0, at + 1);
      return true;
    }
    if (numbers[index] === 1) {
      if (path.length === 1 && path[0] === index) return false;
      path = [index];
      return true;
    }
    if (canAppend(index)) {
      path.push(index);
      return true;
    }
    return false;
  }

  function onPointerDown(event) {
    if (solved) return;
    const index = cellAt(event.clientX, event.clientY);
    if (index < 0) return;
    event.preventDefault();
    dragPointer = event.pointerId;
    board.setPointerCapture?.(event.pointerId);
    if (apply(index)) {
      haptic();
      refresh();
    }
  }

  function onPointerMove(event) {
    if (dragPointer === null || event.pointerId !== dragPointer || solved) return;
    const index = cellAt(event.clientX, event.clientY);
    if (index < 0) return;
    if (apply(index)) {
      haptic();
      refresh();
    }
  }

  function endDrag(event) {
    if (dragPointer === null) return;
    if (event && event.pointerId !== undefined && event.pointerId !== dragPointer) return;
    dragPointer = null;
  }

  board.addEventListener('pointerdown', onPointerDown);
  board.addEventListener('pointermove', onPointerMove);
  board.addEventListener('pointerup', endDrag);
  board.addEventListener('pointercancel', endDrag);
  board.addEventListener('lostpointercapture', endDrag);
  board.addEventListener('contextmenu', (event) => event.preventDefault());

  // Restore a saved path, dropping anything that does not validate.
  if (saved && Number.isInteger(saved.hints) && saved.hints > 0) hints = saved.hints;
  if (saved && Array.isArray(saved.path)) {
    for (const index of saved.path) {
      if (!Number.isInteger(index) || index < 0 || index >= size) break;
      if (!apply(index)) break;
    }
  }

  refresh();

  return {
    getState() {
      return { path: path.slice(), hints };
    },
    destroy() {
      board.removeEventListener('pointerdown', onPointerDown);
      board.removeEventListener('pointermove', onPointerMove);
      board.removeEventListener('pointerup', endDrag);
      board.removeEventListener('pointercancel', endDrag);
      board.removeEventListener('lostpointercapture', endDrag);
      host.replaceChildren();
    },
  };
}

export const zip = {
  id: 'zip',
  name: 'Zip',
  tagline: 'One line through every cell',
  accent: 'violet',
  icon: 'zip',
  defaultDifficulty: 'medium',
  difficulties: Object.entries(DIFFICULTIES).map(([id, config]) => ({ id, label: config.label })),
  generate: generateZip,
  create: createZip,
  rules: [
    'Start on 1 and draw a single line.',
    'The line must pass through every cell exactly once.',
    'Visit the numbers in order: 1, 2, 3 … up to the last one.',
    'Dark bars between cells are walls — the line cannot cross them.',
    'Hint backs your line up to its last correct cell, or draws the next few.',
  ],
};
